INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Winona Ryder', NULL, 'winona-ryder', 'Female', 'Acting', '1971-10-29', NULL, 'Winona, Minnesota, USA', 'Winona Laura Horowitz, known professionally as Winona Ryder, is an American actress. One of the most iconic stars of the 1990s, she has received a Golden Globe Award and nominations for two Academy Awards, a BAFTA Award, and four Screen Actors Guild Awards. She is widely celebrated for Stranger Things, Beetlejuice, Edward Scissorhands, and Little Women.', 'people/winona-ryder.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 05:17:13', '2026-10-29 05:17:13') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = 1, `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Tracee Ellis Ross', NULL, 'tracee-ellis-ross', 'Female', 'Acting', '1972-10-29', NULL, 'Los Angeles, California, USA', 'Tracee Joy Silberstein, known professionally as Tracee Ellis Ross, is an American actress, singer, and television host. She is known for her acclaimed lead roles in comedy series Girlfriends and Black-ish, which earned her six NAACP Image Awards and a Golden Globe Award for Best Actress in a Comedy.', 'people/tracee-ellis-ross.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 05:17:13', '2026-10-29 05:17:13') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = 1, `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Ben Foster', NULL, 'ben-foster', 'Male', 'Acting', '1980-10-29', NULL, 'Boston, Massachusetts, USA', 'Benjamin A. Foster is an American actor known for his intense performances. His acclaimed film roles include Hell or High Water, 3:10 to Yuma, The Messenger, Leave No Trace, Lone Survivor, and Warcraft.', 'people/ben-foster.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 05:17:13', '2026-10-29 05:17:13') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = 1, `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Kriti Kharbanda', NULL, 'kriti-kharbanda', 'Female', 'Acting', '1990-10-29', NULL, 'New Delhi, India', 'Kriti Kharbanda is an Indian actress who works primarily in Hindi, Kannada, and Telugu cinema. She has received critical acclaim for Shaadi Mein Zaroor Aana, Housefull 4, Taish, and Googly, winning a SIIMA Award.', 'people/kriti-kharbanda.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 05:17:13', '2026-10-29 05:17:13') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = 1, `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Ananya Panday', NULL, 'ananya-panday', 'Female', 'Acting', '1998-10-30', NULL, 'Mumbai, Maharashtra, India', 'Ananya Panday is an Indian actress who works in Hindi films. The daughter of actor Chunky Panday, she began her acting career in 2019 with Student of the Year 2 and Pati Patni Aur Woh, which won her the Filmfare Award for Best Female Debut. She has earned wide critical acclaim for Gehraiyaan, Kho Gaye Hum Kahan, and Prime Video\'s Call Me Bae and CTRL.', 'people/ananya-panday.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 05:17:15', '2026-10-29 05:17:15') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = 1, `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Nia Long', NULL, 'nia-long', 'Female', 'Acting', '1970-10-30', NULL, 'Brooklyn, New York City, USA', 'Nitara Carlynn Nia Long is an American actress. Known for her work in Black cinema, she rose to prominence for her roles in Boyz n the Hood (1991), Friday (1995), Soul Food (1997), and The Best Man (1999). Her accolades include three NAACP Image Awards and a Black Reel Award.', 'people/nia-long.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 05:17:17', '2026-10-29 05:17:17') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = 1, `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Kevin Pollak', NULL, 'kevin-pollak', 'Male', 'Acting', '1957-10-30', NULL, 'San Francisco, California, USA', 'Kevin Elliot Pollak is an American actor, comedian, and podcast host. He is known for iconic roles in A Few Good Men (1992), Grumpy Old Men (1993), The Usual Suspects (1995), and Casino (1995), as well as Moishe Maisel in the Amazon Prime series The Marvelous Mrs. Maisel.', 'people/kevin-pollak.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 05:17:19', '2026-10-29 05:17:19') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = 1, `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `social_links`, `website`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('Matthew Morrison', NULL, 'matthew-morrison', 'Male', 'Acting', '1978-10-30', NULL, 'Fort Ord, California, USA', 'Matthew James Morrison is an American actor, dancer, and singer-songwriter. He is best known for starring in multiple Broadway and off-Broadway productions, as well as his celebrated role as Will Schuester on Fox\'s musical comedy-drama television series Glee (2009–2015), which earned him Tony, Emmy, and Golden Globe nominations.', 'people/matthew-morrison.jpg', NULL, NULL, 1, 'active', 1, '2026-10-29 05:17:21', '2026-10-29 05:17:21') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `stage_name` = VALUES(`stage_name`), `gender` = VALUES(`gender`), `known_for_department` = VALUES(`known_for_department`), `birth_date` = VALUES(`birth_date`), `birth_place` = VALUES(`birth_place`), `biography` = VALUES(`biography`), `photo_path` = VALUES(`photo_path`), `is_featured` = 1, `status` = 'active', `is_active` = 1, `updated_at` = VALUES(`updated_at`);
